import{_ as t,o as r,c as e,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Система гарантий «Путь для Каждого»","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0008-人人有路保障体系.md","filePath":"ru/0008-人人有路保障体系.md"}'),d={name:"ru/0008-人人有路保障体系.md"};function l(o,a,h,n,s,p){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="система-гарантии-«путь-для-каждого»" tabindex="-1">Система гарантий «Путь для Каждого» <a class="header-anchor" href="#система-гарантии-«путь-для-каждого»" aria-label="Permalink to &quot;Система гарантий «Путь для Каждого»&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>08</td></tr><tr><td>Модуль</td><td>Общие принципы и базовые установки</td></tr><tr><td>Ключевые слова</td><td>Путь для Каждого, Система гарантий, Эволюционный минимум, Слабые группы, Всеобщая выгода</td></tr></tbody></table><h2 id="i-базовое-определение-«пути-для-каждого»" tabindex="-1">I. Базовое определение «Пути для Каждого» <a class="header-anchor" href="#i-базовое-определение-«пути-для-каждого»" aria-label="Permalink to &quot;I. Базовое определение «Пути для Каждого»&quot;">​</a></h2><p>«Путь для Каждого» — одна из центральных социальных целей Симбиотической Цивилизации Якоря: гарантировать каждой жизни в Хэн Юаньчжоу — независимо от расы, происхождения, дарования, уровня и богатства — возможность получить подходящий эволюционный путь и шанс собственными усилиями достичь повышения уровня и совершенствования жизни. «Иметь путь» означает не только наличие методов культивации для изучения, но и наличие ресурсов для использования, наставников для вопросов, среды для практики и институтов для опоры.</p><p>«Путь для Каждого» и «Больше Труда — Больше Награды» — две опоры системы распределения симбиотической цивилизации. Первый принцип решает проблему «эффективности», стимулируя сильных создавать больше ценности; второй решает проблему «справедливости», гарантируя, что слабые не будут отброшены эволюционной системой. Они взаимодополняют друг друга; без одного не обойтись. Без «Пути для Каждого» принцип «Больше Труда — Больше Награды» выродится в закон джунглей; без «Больше Труда — Больше Награды» «Путь для Каждого» выродится в уравниловку.</p><h2 id="ii-необходимость-«пути-для-каждого»" tabindex="-1">II. Необходимость «Пути для Каждого» <a class="header-anchor" href="#ii-необходимость-«пути-для-каждого»" aria-label="Permalink to &quot;II. Необходимость «Пути для Каждого»&quot;">​</a></h2><p>Установление системы гарантий основано на следующих глубоких пониманиях:</p><h3 id="_2-1-право-на-эволюцию-—-самое-базовое-право-жизни" tabindex="-1">2.1 Право на эволюцию — самое базовое право жизни <a class="header-anchor" href="#_2-1-право-на-эволюцию-—-самое-базовое-право-жизни" aria-label="Permalink to &quot;2.1 Право на эволюцию — самое базовое право жизни&quot;">​</a></h3><p>В культивационных цивилизациях право на эволюцию — не только право на развитие, но и право на выживание. При столкновении с различными опасностями вселенной (колебания плоскостей, энергетические бури, вторжения чужих рас) жизни с низкими уровнями имеют гораздо меньшую вероятность выживания, чем жизни с высокими уровнями. Поэтому гарантия эволюционного пути для каждой жизни — по сути гарантия базового права на выживание каждой жизни.</p><h3 id="_2-2-различия-в-начальных-дарованиях-не-должны-определять-судьбу-эволюции" tabindex="-1">2.2 Различия в начальных дарованиях не должны определять судьбу эволюции <a class="header-anchor" href="#_2-2-различия-в-начальных-дарованиях-не-должны-определять-судьбу-эволюции" aria-label="Permalink to &quot;2.2 Различия в начальных дарованиях не должны определять судьбу эволюции&quot;">​</a></h3><p>Начальные дарования каждой жизни (расовый талант, семейное происхождение, плоскость рождения, врождённые задатки и т.д.) сильно различаются. В эпоху хищничества эти различия часто увеличивались до непреодолимых пропастей — жизни из хороших семей монополизировали качественные ресурсы, а жизни из бедных семей не могли получить даже базовые методы культивации. Симбиотическая цивилизация считает, что различия в начальных дарованиях объективно существуют, но не должны становиться единственным фактором, определяющим эволюционную судьбу. Роль институтов — компенсировать эти начальные различия, давая каждой жизни шанс изменить судьбу собственными усилиями.</p><h3 id="_2-3-отброшенные-индивиды-—-потенциальная-потеря-цивилизации" tabindex="-1">2.3 Отброшенные индивиды — потенциальная потеря цивилизации <a class="header-anchor" href="#_2-3-отброшенные-индивиды-—-потенциальная-потеря-цивилизации" aria-label="Permalink to &quot;2.3 Отброшенные индивиды — потенциальная потеря цивилизации&quot;">​</a></h3><p>Каждая жизнь обладает эволюционным потенциалом; многим просто не хватает подходящих путей и ресурсов. Жизнь, борющаяся на дне, может после получения подходящей системы культивации проявить поразительный талант; индивид, считающийся «неудачником», возможно, просто не нашёл подходящее эволюционное направление. Смысл системы гарантий — не отказываться ни от одного потенциального эволюционера, максимально расширяя кадровый резерв цивилизации.</p><h3 id="_2-4-всеобщая-эволюция-—-основа-вознесения-вселеннои" tabindex="-1">2.4 Всеобщая эволюция — основа вознесения вселенной <a class="header-anchor" href="#_2-4-всеобщая-эволюция-—-основа-вознесения-вселеннои" aria-label="Permalink to &quot;2.4 Всеобщая эволюция — основа вознесения вселенной&quot;">​</a></h3><p>Общее вознесение вселенной не может опираться лишь на немногих верховных сильных, а требует всеобщей эволюции Десяти Тысяч Рас и всех существ. Эффективность сети якорей положительно коррелирует с количеством и качеством подключённых жизней. Когда больше жизней подключается к системам культивации и повышает уровни, циркуляция энергии и работа законов всей сети якорей становятся стабильнее и эффективнее, а процесс вознесения вселенной ускоряется.</p><h2 id="iii-иерархическая-структура-системы-гарантии" tabindex="-1">III. Иерархическая структура системы гарантий <a class="header-anchor" href="#iii-иерархическая-структура-системы-гарантии" aria-label="Permalink to &quot;III. Иерархическая структура системы гарантий&quot;">​</a></h2><p>Система гарантий делится на четыре уровня, образуя полную цепь гарантий от базового к продвинутому:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Название</th><th>Содержание гарантии</th><th>Охват</th></tr></thead><tbody><tr><td>Первый уровень</td><td>Базовая гарантия</td><td>Бесплатные методы культивации, минимальная выдача ресурсов, базовые медицинские и образовательные услуги</td><td>Все жизни, без порога</td></tr><tr><td>Второй уровень</td><td>Целевая поддержка</td><td>Дополнительные ресурсы, наставники и техническая поддержка для слабых групп</td><td>Индивиды и расы со слабыми начальными дарованиями</td></tr><tr><td>Третий уровень</td><td>Расширение возможностей</td><td>Продвинутые возможности культивации, межплоскостные обмены, права участия в особых проектах</td><td>Культиваторы с потенциалом, но недостатком ресурсов</td></tr><tr><td>Четвёртый уровень</td><td>Стимулирование достижений</td><td>Ресурсы высокого уровня, продвинутый доступ к якорям, цивилизационные почести</td><td>Культиваторы с выдающимися заслугами</td></tr></tbody></table><p>Первый уровень «ловит дно», гарантируя, что никто не отброшен; второй «компенсирует различия», восполняя различия начальных дарований; третий «взращивает лучших», давая потенциальным индивидам больше возможностей; четвёртый «стимулирует», вознаграждая выдающихся. Четыре уровня идут ступенчато, образуя полную систему гарантий и стимулов.</p><h2 id="iv-конкретное-содержание-базовои-гарантии" tabindex="-1">IV. Конкретное содержание базовой гарантии <a class="header-anchor" href="#iv-конкретное-содержание-базовои-гарантии" aria-label="Permalink to &quot;IV. Конкретное содержание базовой гарантии&quot;">​</a></h2><p>Базовая гарантия — ядро системы, включающее следующее:</p><h3 id="_4-1-гарантия-методов-культивации" tabindex="-1">4.1 Гарантия методов культивации <a class="header-anchor" href="#_4-1-гарантия-методов-культивации" aria-label="Permalink to &quot;4.1 Гарантия методов культивации&quot;">​</a></h3><p>Базовые методы Трёхсот Изначальных Систем Культивации открыты для всех жизней бесплатно, без какого-либо порога. Каждая жизнь может свободно выбрать подходящую систему культивации — без оплаты, без вступления в конкретные секты, без проверки квалификации. Сеть якорей предоставляет оценку совместимости систем, помогая практикам найти наиболее подходящий путь.</p><h3 id="_4-2-гарантия-ресурсов-культивации" tabindex="-1">4.2 Гарантия ресурсов культивации <a class="header-anchor" href="#_4-2-гарантия-ресурсов-культивации" aria-label="Permalink to &quot;4.2 Гарантия ресурсов культивации&quot;">​</a></h3><p>Через Систему Подряда, Связанного с Результатом, и публичное распределение ресурсов каждая жизнь обеспечивается ресурсами, необходимыми для базовой культивации. Базовое распределение включает: минимальное энергоснабжение, базовые пилюли культивации, права доступа к общему оборудованию культивации. Для плоскостей с дефицитом ресурсов проводится межплоскостное перераспределение через сеть якорей.</p><h3 id="_4-3-гарантия-среды-культивации" tabindex="-1">4.3 Гарантия среды культивации <a class="header-anchor" href="#_4-3-гарантия-среды-культивации" aria-label="Permalink to &quot;4.3 Гарантия среды культивации&quot;">​</a></h3><p>Цивилизация построила публичные площадки культивации на каждой планете и в каждой плоскости, включая публичные комнаты культивации, зоны регулировки концентрации энергии, комнаты постижения законов и т.д. Эти площадки открыты для всех жизней бесплатно или по низкой цене, гарантируя даже самому бедному практику подходящую среду.</p><h3 id="_4-4-гарантия-наставничества" tabindex="-1">4.4 Гарантия наставничества <a class="header-anchor" href="#_4-4-гарантия-наставничества" aria-label="Permalink to &quot;4.4 Гарантия наставничества&quot;">​</a></h3><p>Создана межрасовая сеть наставников: продвинутые практики обязаны давать базовое руководство начинающим. Каждый начинающий может через сеть якорей подать заявку на подбор наставника и бесплатно получить базовые ответы и советы по культивации. Для практиков с особыми трудностями предоставляется индивидуальное целевое руководство.</p><h3 id="_4-5-гарантия-медицины-и-реабилитации" tabindex="-1">4.5 Гарантия медицины и реабилитации <a class="header-anchor" href="#_4-5-гарантия-медицины-и-реабилитации" aria-label="Permalink to &quot;4.5 Гарантия медицины и реабилитации&quot;">​</a></h3><p>Симбиотическая медицинская система предоставляет практикам бесплатную базовую медицину и услуги реабилитации при отклонениях культивации. Травмы в процессе практики, помешательство от отклонения, энергетические расстройства и т.п. получают своевременное лечение и реабилитацию, гарантируя, что практик не потеряет эволюционную способность из-за несчастных случаев.</p><h2 id="v-объекты-и-методы-целевои-поддержки" tabindex="-1">V. Объекты и методы целевой поддержки <a class="header-anchor" href="#v-объекты-и-методы-целевои-поддержки" aria-label="Permalink to &quot;V. Объекты и методы целевой поддержки&quot;">​</a></h2><p>Целевая поддержка направлена на следующие слабые группы:</p><ul><li><strong>Индивиды со слабыми дарованиями</strong>: индивиды с плохими врождёнными задатками и медленным прогрессом получают дополнительные ресурсы и индивидуальное руководство</li><li><strong>Обнищавшие расы</strong>: расы с общей нехваткой ресурсов и низким уровнем эволюции получают целевую поддержку из расового фонда развития</li><li><strong>Посткатастрофные группы</strong>: группы, потерявшие дом и ресурсы из-за плоскостных катастроф, войн и т.п., получают экстренную помощь и поддержку восстановления</li><li><strong>Практики с инвалидностью</strong>: практики с физической или психической инвалидностью по разным причинам получают специальное вспомогательное оборудование и индивидуальные планы культивации</li><li><strong>Аномальные жизни</strong>: аномальные жизни, не вписывающиеся в обычные системы культивации, получают специальную оценку и индивидуальные эволюционные пути</li></ul><p>Методы целевой поддержки включают: дополнительные ресурсы, индивидуальное наставничество, индивидуальные планы культивации, предоставление специального оборудования, межплоскостные обмены и т.д. Цель — помочь слабым группам достичь базового эволюционного уровня, после чего постепенно перейти к нормальной системе распределения «Больше Труда — Больше Награды».</p><h2 id="vi-источники-финансирования-и-ресурсов-системы-гарантии" tabindex="-1">VI. Источники финансирования и ресурсов системы гарантий <a class="header-anchor" href="#vi-источники-финансирования-и-ресурсов-системы-гарантии" aria-label="Permalink to &quot;VI. Источники финансирования и ресурсов системы гарантий&quot;">​</a></h2><p>Работа системы требует значительных ресурсов и средств, источниками которых являются:</p><ol><li><strong>Доходы от публичных ресурсов</strong>: продукция публичных духовных жил, энергетических рудных жил, медицинских полей и других ресурсов, напрямую управляемых цивилизацией</li><li><strong>Регулирующий налог на вклад</strong>: определённая доля «регулирующего налога на вклад» с высоких вкладчиков для работы системы (прогрессивная ставка, не выше 30%)</li><li><strong>Фонд развития цивилизации</strong>: избыточная энергия, производимая сетью якорей, частично направляется в фонд развития цивилизации</li><li><strong>Доходы от лицензий на технологии</strong>: плата за лицензии на технологии инженерии законов, принадлежащие цивилизации</li><li><strong>Пожертвования и завещания</strong>: добровольные пожертвования индивидов и рас</li></ol><p>Доходы и расходы системы управляются Комитетом по гарантиям при Собрании Республики Десяти Тысяч Рас, счета периодически публикуются для всех жизней и находятся под надзором.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Система гарантий «Путь для Каждого» — краеугольный камень социальной справедливости Симбиотической Цивилизации Якоря. Она гарантирует, что в цивилизации, центрированной на культивации и эволюции, ни одна жизнь не будет отброшена эволюционной системой из-за происхождения, дарований или бедности. «Путь для Каждого» — не уравниловка, а предоставление каждой жизни справедливого старта, восходящего канала и обещания не быть оставленным. Под защитой «Пути для Каждого» каждая жизнь может найти свой собственный эволюционный путь.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Принципы распределения «Больше Труда — Больше Награды»)</li><li>07-自生自长进化法则 (Закон Самостоятельного Роста и Саморазвития)</li><li>38-共生医疗体系 (Симбиотическая медицинская система)</li></ul>',43)])])}const u=t(d,[["render",l]]);export{_ as __pageData,u as default};
